<script lang="ts">
  import {onMount} from 'svelte';
  import {loadBooks,saveBooks,type BookConfiguration,type BookSettings} from '../../api/books';
  import {loadWorkflow,type WorkflowState} from '../../api/workflows';
  import {requestConfirmation} from '../../confirmation';
  let {moduleUid,moduleName,dirty=$bindable(false)}:{moduleUid:string;moduleName:string;dirty?:boolean}=$props();
  let config=$state<BookConfiguration|null>(null);let draft=$state<BookSettings|null>(null);let saved=$state('');let busy=$state(false);let error=$state('');let notice=$state('');let stages=$state<WorkflowState[]>([]);
  $effect(()=>{dirty=!!draft&&JSON.stringify(draft)!==saved;});
  onMount(()=>{let active=true;void loadBooks(moduleUid).then(v=>{if(active){config=v;draft=structuredClone(v.settings);saved=JSON.stringify(v.settings);}}).catch(e=>{if(active)error=e.message;});void loadWorkflow(moduleUid).then(v=>{if(active&&v.definition.enabled)stages=v.definition.states;}).catch(()=>{});return()=>{active=false;};});
  async function save(event:SubmitEvent){event.preventDefault();if(!draft||!config||busy)return;
    if(draft.closed_through!==config.settings.closed_through&&draft.closed_through&&!await requestConfirmation({title:'Close this accounting period?',description:`Posting dates through ${draft.closed_through} will be blocked. This cutoff cannot be moved backwards.`,confirmLabel:'Close period and save',tone:'danger'}))return;
    busy=true;error='';notice='';try{config=await saveBooks(moduleUid,config.revision,draft);draft=structuredClone(config.settings);saved=JSON.stringify(config.settings);notice='Book settings saved. Create accounts or stock items in the module’s Books workspace.';}catch(e){error=e instanceof Error?e.message:String(e);}finally{busy=false;}
  }
  function operator(level:number,checked:boolean){if(draft)draft.operator_levels=checked?[...new Set([...draft.operator_levels,level])].sort():draft.operator_levels.filter(v=>v!==level);}
</script>
<section class="book-settings">
  <h2>Accounting & stock · {moduleName}</h2>
  <p>Optional operational books for this module. Enabling a book creates no business records, accounts, balances or stock.</p>
  {#if error}<p class="notice error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
  {#if draft&&config}<form onsubmit={save}><fieldset disabled={busy||!config.can_configure}>
    <div class="settings-grid"><section><h3>Accounting book</h3><label class="choice"><input type="checkbox" bind:checked={draft.accounting}/>Enable balanced journal entries</label><label>Currency code<input maxlength="3" placeholder="e.g. PHP" bind:value={draft.currency} oninput={()=>{if(draft)draft.currency=draft.currency.toUpperCase();}}/></label><label>Money decimal places<select bind:value={draft.money_decimals}>{#each [0,1,2,3,4,5,6] as n}<option value={n}>{n}</option>{/each}</select></label><label>Close posting dates through<input type="date" bind:value={draft.closed_through} min={config.settings.closed_through||undefined}/></label><small>Currency and precision become fixed after the first journal. Closing a period is permanent. Corrections use a new reversing journal, never an edited original.</small></section>
    <section><h3>Stock book</h3><label class="choice"><input type="checkbox" bind:checked={draft.inventory}/>Enable stock and reservations</label><label>Quantity decimal places<select bind:value={draft.stock_decimals}>{#each [0,1,2,3,4,5,6] as n}<option value={n}>{n}</option>{/each}</select></label><small>Precision becomes fixed after creating the first item. Receive opening stock explicitly; reserve, release, consume or issue it without allowing negative available stock.</small></section></div>
    <section><h3>Who may operate this book?</h3><p>Book operators see the <strong>entire book</strong>, independently of creator-only record visibility. They also need this module’s Read, Edit and Reports permissions. Other record users cannot see book balances.</p><div class="operator-choices"><label class="choice"><input type="checkbox" checked disabled/>Administrator (always)</label>{#each [{level:1,name:'Manager'},{level:2,name:'Editor'}] as role}<label class="choice"><input type="checkbox" checked={draft.operator_levels.includes(role.level)} onchange={e=>operator(role.level,e.currentTarget.checked)}/>{role.name}</label>{/each}</div><small>Only module configurators may create chart accounts and item definitions. No viewer can post.</small></section>
    <section><h3>Source-record approval</h3><label>Require a completed process stage before new posting<select bind:value={draft.required_stage}><option value="">No stage requirement — manual book entries allowed</option>{#each stages as stage}<option value={stage.key}>{stage.name}</option>{/each}{#if draft.required_stage&&!stages.some(v=>v.key===draft!.required_stage)}<option value={draft.required_stage}>{draft.required_stage} · unavailable; posting will be blocked</option>{/if}</select></label><small>If required, operators open a saved record and use its Books button. MX checks its exact revision and decision in the same transaction as posting. Reversals and finishing existing stock holds do not require a new source approval.</small></section>
    <p class="notice">Saving starts permanent book audit history: archive this module instead of deleting it afterward. These are operational books, not a certified accounting, tax, payroll or full ERP suite. Formulas and ordinary record edits do not automatically create postings.</p>
    <button class="button primary" type="submit" disabled={busy||!dirty}>{busy?'Saving book settings…':'Save book settings'}</button>
  </fieldset></form>{:else if !error}<p role="status">Loading book settings…</p>{/if}
</section>
<style>
  .book-settings{max-width:70rem}.book-settings>p,small{color:var(--muted);line-height:1.6}h2{font-size:1.2rem}h3{font-size:1rem;margin:0 0 .75rem}fieldset{border:0;padding:0;min-width:0;display:grid;gap:1.25rem}.settings-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}section section{border:1px solid var(--line);border-radius:.65rem;padding:1rem;min-width:0}label:not(.choice){display:grid;gap:.4rem;margin:.75rem 0}.choice{display:flex;align-items:center;gap:.6rem;min-height:2.5rem}.operator-choices{display:flex;flex-wrap:wrap;gap:1rem}small{display:block;font-size:.875rem}.button{justify-self:start}input:not([type=checkbox]),select{width:100%;min-width:0;box-sizing:border-box}@media(max-width:700px){.settings-grid{grid-template-columns:1fr}}
</style>
